create or replace function public.due_maintenance(as_of date default current_date) returns table(item_type text,item_id uuid,unit_id uuid,due_date date,due_mileage integer) language sql stable security definer set search_path=public as $$ select 'part'::text,id,unit_id,next_due_date,next_due_mileage from part_replacements where deleted_at is null and (next_due_date<=as_of or next_due_mileage<=(select current_mileage from units where units.id=part_replacements.unit_id)) union all select 'tire'::text,id,unit_id,next_due_date,next_due_mileage from tire_installations where deleted_at is null and replaced_by_id is null and (next_due_date<=as_of or next_due_mileage<=(select current_mileage from units where units.id=tire_installations.unit_id)) $$;
